 assert(path.isAbsolute(env.COLLATERAL_AUCTION_CURRENT_SOURCE_PATH));assert.match(env.COLLATERAL_AUCTION_CURRENT_SOURCE_SHA256,/^[a-f0-9]{64}$/);assert.match(env.COLLATERAL_AUCTION_CURRENT_SOURCE_REVISION,/^[a-f0-9]{40}$/);assert(path.isAbsolute(env.COLLATERAL_AUCTION_CURRENT_PROOFS));
