export function verifyCurrentAuctionSource(root,env){
 const git=(...args)=>execFileSync('git',args,{cwd:root,windowsHide:true,maxBuffer:64*1024*1024}),text=(...args)=>git(...args).toString('utf8').trim();
 const file=env.COLLATERAL_AUCTION_CURRENT_SOURCE_PATH;assert(fs.lstatSync(file).isFile()&&!fs.lstatSync(file).isSymbolicLink());const bytes=fs.readFileSync(file);assert.equal(hash(bytes),env.COLLATERAL_AUCTION_CURRENT_SOURCE_SHA256);const captured=JSON.parse(bytes);
 assert.deepEqual(Object.keys(captured).sort(),['entries','gitTree','phase','revision']);assert(Array.isArray(captured.entries));assert.equal(captured.phase,'ACTUAL_CLEAN_CURRENT_N24_SOURCE');assert.equal(captured.revision,env.COLLATERAL_AUCTION_CURRENT_SOURCE_REVISION);assert.equal(text('rev-parse','HEAD'),captured.revision);assert.equal(text('rev-parse','HEAD^{tree}'),captured.gitTree);assert.equal(text('status','--porcelain','--untracked-files=no'),'');
 git('merge-base','--is-ancestor',CURRENT_SOURCE_ANCESTOR,captured.revision);
 const actual=git('ls-tree','-r','-z','--full-tree','HEAD').toString('utf8').split('\0').filter(Boolean).map(row=>{const m=/^(100644|100755) blob ([a-f0-9]{40})\t(.+)$/.exec(row);assert(m,'Only actual regular tracked blobs');return{mode:m[1],blob:m[2],file:m[3]};});
 assert.equal(captured.entries.length,actual.length);for(let i=0;i<actual.length;i++){
  const a=actual[i],r=captured.entries[i];assert.deepEqual(Object.keys(r).sort(),['blob','file','gitSHA256','mode','normalization','rawSHA256']);assert.deepEqual({mode:r.mode,blob:r.blob,file:r.file},a);assert(!path.isAbsolute(r.file)&&!r.file.split('/').includes('..'));
  const target=path.join(root,r.file),stat=fs.lstatSync(target);assert(stat.isFile()&&!stat.isSymbolicLink());const raw=fs.readFileSync(target);assert.equal(hash(raw),r.rawSHA256);let canonical;
  if(r.normalization==='binary')canonical=raw;else{assert(['LF','CRLF'].includes(r.normalization));const decoded=raw.toString('utf8');assert(Buffer.from(decoded).equals(raw)&&!decoded.includes('\0'),'Only lossless non-NUL UTF8 text may normalize');const lf=decoded.replaceAll('\r\n','\n');assert(!lf.includes('\r'));assert.equal(decoded,r.normalization==='LF'?lf:lf.replaceAll('\n','\r\n'));canonical=Buffer.from(lf);}
  assert.equal(hash(canonical),r.gitSHA256);assert.equal(crypto.createHash('sha1').update(Buffer.from('blob '+canonical.length+'\0')).update(canonical).digest('hex'),a.blob,'Every captured byte belongs to its actual Git blob, no per-file subprocess or source substitution');
 }
 for(const directory of ['public/art','public/art/hype']){const suffixes=directory==='public/art'?['.jpg','.jpeg','.png','.webp','.woff2','.mp4','.m4a']:['.mp4','.m4a'],eligible=name=>suffixes.includes(name.slice(name.lastIndexOf('.')).toLowerCase()),expected=actual.filter(r=>path.posix.dirname(r.file)===directory&&eligible(path.posix.basename(r.file))).map(r=>path.posix.basename(r.file)).sort();assert.deepEqual(fs.readdirSync(path.join(root,directory)).filter(eligible).sort(),expected,'No unknown eligible boot input');}
 assert.equal(text('rev-parse','HEAD'),captured.revision);assert.equal(text('status','--porcelain','--untracked-files=no'),'');return{revision:captured.revision,gitTree:captured.gitTree,files:actual.length,captureSHA256:hash(bytes)};
}
